class Solution {
public:
    int minNumberOfHours(int initialEnergy, int initialExperience,
                         vector<int>& energy, vector<int>& experience) {
        int e = initialEnergy, x = initialExperience, ans = 0;
        for (int i = 0; i < (int)energy.size(); i++) {
            while (e <= energy[i]) { e++; ans++; }
            while (x <= experience[i]) { x++; ans++; }
            e -= energy[i];
            x += experience[i];
        }
        return ans;
    }
};

