class Solution:
    def minNumberOfHours(self, initialEnergy: int, initialExperience: int, energy: List[int], experience: List[int]) -> int:
        e, x, ans = initialEnergy, initialExperience, 0
        for de, dx in zip(energy, experience):
            if e <= de:
                ans += de - e + 1
                e = de + 1
            if x <= dx:
                ans += dx - x + 1
                x = dx + 1
            e -= de
            x += dx
        return ans

